/**
 * The zh-CN catalogue: English source string -> Chinese sentence.
 *
 * Generated by `scripts/i18n/build-catalog.ts`, translated in reviewable batches, and keyed by the
 * exact source string so `t("Save")` finds `Save`. Entries whose value is empty are treated as
 * untranslated by `t()` and fall back to the English source.
 *
 * Keep keys verbatim. A key with a stray space or a changed apostrophe silently stops matching.
 */
export const ZH_CN: Record<string, string> = {
  Hello: "你好",
};